\label{A:disturbance}(Prior assumption on disturbance and noise)
$d$ and $v$ are bounded as:
\begin{equation}\label{Eq:dist_bound}
\begin{array}{lll}
|d_j(t)|&\leq&\epsilon_{d_j}\\
|v_j(t)|&\leq&\epsilon_{v_j}
\end{array},\,\forall t\in{\mathbb Z},\,\forall j=1,\hdots,n_y,
\end{equation}
where $\epsilon_{d_j}$ and $\epsilon_{v_j}$ are positive scalars.\

\label{A:system_class}(Prior assumption on the system)
The plant belongs to the following model set: $H\in \mathcal{F}(0)$, with
\begin{equation}\label{Eq:system_set}
\mathcal{F}(0) \doteq \left\{H\in {\mathbb R}^{n_y\times n_um}: A_{j}(0)H_j\leq b_{j}(0), j=1,\hdots, n_y \right\},
\end{equation}
where the inequalities in \eqref{Eq:system_set} should be interpreted as element-wise inequalities and each matrix $A_{j}(0)\in {\mathbb R}^{r_{j}(0)\times n_um}$ and vector $b_{j}(0) \in {\mathbb R}^{r_{j}(0)}$ define a close and convex set, i.e. a polytope with $r_{j}(0)$ faces.

algorithm.raw:
\begin{itemize}
  \item[1)]At time step $t$, obtain $\tilde{y}(t)$ and update the model set based on the past applied control inputs and measured plant outputs;
\item[2)] Select a nominal model of the plant inside the model set;
  \item[3)]Calculate a sequence of possible future control inputs by solving a finite horizon optimal control problem (FHOCP) that minimizes the weighted $l_2$ norm of the tracking error for the nominal model and enforces input and output constraints for all the models inside the model set;
  \item[4)]Apply the first element of the calculated input sequence, set $t=t+1$, go to 1).
\end{itemize}
\caption{Adaptive MPC algorithm}\label{Alg:RHCOP2}

